param([Parameter(Mandatory=$true)][string]$Dir)
$ErrorActionPreference='Stop';$existing=@(Get-CimInstance Win32_Process -Filter "Name='WINWORD.EXE'"|ForEach-Object{[int]$_.ProcessId});$owned=@();$w=New-Object -ComObject Word.Application;$w.Visible=$false;$w.DisplayAlerts=0
try{$d=$w.Documents.Add();$owned=@(Get-CimInstance Win32_Process -Filter "Name='WINWORD.EXE'"|Where-Object{[int]$_.ProcessId -notin $existing}|ForEach-Object{[int]$_.ProcessId});if(-not $owned.Count){throw 'Word COM PID missing'};$d.Content.Text=('Hoa hoa H'+[char]242+'a hoang hoa');$r=$d.Range($d.Content.Start,$d.Content.End-1);$f=$r.Find;$f.ClearFormatting();$f.Text='Hoa';$f.MatchCase=$true;$case=$f.Execute();$caseText=if($case){$r.Text}else{''};$r=$d.Range($d.Content.Start,$d.Content.End-1);$f=$r.Find;$f.ClearFormatting();$f.Text='hoa';$f.MatchCase=$false;$f.MatchWholeWord=$true;$word=$f.Execute();$wordText=if($word){$r.Text}else{''};$r=$d.Range($d.Content.Start,$d.Content.End-1);$f=$r.Find;$f.ClearFormatting();$f.Text='hoang';$f.MatchCase=$false;$f.MatchWholeWord=$true;$f.Forward=$true;$f.Wrap=0;$f.Replacement.Text='Hoang';$count=$f.Execute('hoang',$false,$true,$false,$false,$false,$true,0,$false,'Hoang',1);$d.SaveAs2("$Dir\word_find_replace_t8_new.docx",16);$d.Close(0);Write-Output ("Word matchCase={0}:{1}; wholeWord={2}:{3}; replaceOne={4}" -f $case,$caseText,$word,$wordText,$count)
 foreach($name in @('word_find_replace_t8_new.docx','app_find_replace_t8_new.docx')){$d=$w.Documents.Open("$Dir\$name",$false,$true);try{Write-Output ("{0}: {1}" -f $name,($d.Content.Text -replace '[\r\a]','').Trim())}finally{$d.Close(0)}}
}finally{if($w){$w.Quit();[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($w)};$owned=@($owned+@(Get-CimInstance Win32_Process -Filter "Name='WINWORD.EXE'"|Where-Object{[int]$_.ProcessId -notin $existing}|ForEach-Object{[int]$_.ProcessId})|Select-Object -Unique);foreach($ownedPid in $owned){$p=Get-Process -Id $ownedPid -ErrorAction SilentlyContinue;if($p){$p|Wait-Process -Timeout 3 -ErrorAction SilentlyContinue};if(Get-Process -Id $ownedPid -ErrorAction SilentlyContinue){Stop-Process -Id $ownedPid -Force -ErrorAction SilentlyContinue}}}
